using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// ── 1) Strongly-typed retrieval ──────────────────────────────────────
// GetTypeInfo<T>() returns JsonTypeInfo<T> directly — no casting needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Typed metadata → {personInfo.Type.Name}, kind={personInfo.Kind}");

// ── 2) Probe without throwing ────────────────────────────────────────
// TryGetTypeInfo returns false when metadata can't be resolved.
// We demonstrate with a resolver that only knows about Person.
var limitedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new LimitedResolver()
};
limitedOptions.MakeReadOnly();

// Person is known → should succeed
bool found = limitedOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo(Person)  → found={found}, type={info?.Type.Name}");

// Order is NOT known → should return false, no exception
bool found2 = limitedOptions.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? info2);
Console.WriteLine($"TryGetTypeInfo(Order)   → found={found2}, info is null: {info2 is null}");

// ── Types ────────────────────────────────────────────────────────────
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

// A resolver that only handles Person
file class LimitedResolver : IJsonTypeInfoResolver
{
    private static readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);
        return null;  // signals "not supported"
    }
}
